//! Deauthentication and disassociation floods — Tier 2.
//!
//! ## Why this is the tier that matters, and not the fanciest one
//!
//! A deauth flood is **jamming performed with entirely legal frames**. It
//! radiates no excess energy, so channel occupancy ([`crate::survey`], Tier 1)
//! and spectral FFT (Tier 3) are both blind to it *by construction* — there is
//! nothing anomalous in the spectrum to find. Only frame inspection sees it.
//!
//! That inverts the usual assumption that the higher tier is the more capable
//! one, and on this hardware it is doubly true: measured 2026-09-04, Tier 1 is
//! unsupported by both drivers (no `get_survey` op) and Tier 3 is absent from
//! the kernel build, so Tier 2 is the only tier available at all.
//!
//! ## The sensor cannot react, and that shapes the output
//!
//! The monitor Pi is emit-only by decision — nothing inbound, updates by
//! physical SD swap. So it detects and *emits*; a subscriber reacts. A verdict
//! therefore carries everything a reaction needs: which client, which BSSID,
//! the rate, and the window it was measured over. There is no back channel on
//! which a subscriber could ask a follow-up question.
//!
//! ## Telling an attack from a busy evening
//!
//! Networks legitimately emit these frames: clients roam, APs reboot, sessions
//! time out. What does not happen legitimately is a **broadcast** deauth — an
//! access point disconnecting one client addresses *that client*, so
//! `ff:ff:ff:ff:ff:ff` is close to a signature on its own, and is weighted far
//! above unicast here.
//!
//! The bias is deliberately toward speaking up: a missed flood is an outage
//! nobody can explain, while a false positive costs one look at a screen that
//! names its own reasoning.

/// The 802.11 management subtypes this module cares about.
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub enum FrameKind {
    /// Subtype 12. The classic disconnect attack.
    Deauthentication,
    /// Subtype 10. Same effect for the client, and often used interchangeably
    /// by attack tooling, so it is counted alongside rather than ignored.
    Disassociation,
}

/// One management frame the radio saw.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub struct FrameObservation {
    /// Monotonic milliseconds, supplied by the caller — this module holds no
    /// clock, so every threshold is testable exactly rather than by sleeping.
    pub at_ms: u64,
    pub kind: FrameKind,
    /// The BSSID the frame claims to come from. "Claims" is the operative
    /// word: it is trivially spoofed, which is the attack.
    pub bssid: String,
    /// Destination. `ff:ff:ff:ff:ff:ff` is a broadcast disconnect.
    pub target: String,
    /// The 802.11 reason code, when the capture carried one.
    pub reason: Option<u16>,
    /// The channel the frame was captured on, from the radiotap header.
    ///
    /// Carried PER OBSERVATION rather than assumed from the interface: a
    /// hopping radio sees frames on several channels, and reporting the last
    /// channel the interface happened to sit on would name the wrong one.
    pub freq_mhz: u16,
    /// Addr2 — who TRANSMITTED it, as claimed. Distinct from `bssid` (addr3):
    /// a spoofing attacker usually forges both, but they need not agree, and a
    /// disagreement is itself a finding.
    pub transmitter: String,
    /// Received signal, dBm, when the capture carried it.
    ///
    /// THE ONE FIELD AN ATTACKER CANNOT FORGE. Every address in a management
    /// frame is trivially spoofed, which is the whole attack; the power the
    /// radio actually received is a physical measurement of the transmitter's
    /// proximity. It is the only thing here that constrains WHERE the frames
    /// are coming from.
    pub signal_dbm: Option<i8>,
}

impl FrameObservation {
    pub fn is_broadcast(&self) -> bool {
        self.target.eq_ignore_ascii_case("ff:ff:ff:ff:ff:ff")
    }
}

/// How the detector judges. Every field is a policy choice a reader can argue
/// with, which is why they are named rather than buried as literals.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Policy {
    /// The window observations are counted over.
    pub window_ms: u64,
    /// Unicast frames in one window before it reads as elevated.
    pub elevated_frames: u32,
    /// Unicast frames in one window before it reads as a flood.
    pub flood_frames: u32,
    /// Broadcast disconnects tolerated in a window before it is a flood
    /// regardless of volume. An AP disconnecting a client addresses that
    /// client, so this is deliberately tiny.
    pub broadcast_flood_frames: u32,
}

impl Policy {
    /// Defaults chosen to speak up. A home network sees a handful of these an
    /// hour; thirty in ten seconds is not roaming.
    pub const fn sensible() -> Self {
        Self {
            window_ms: 10_000,
            elevated_frames: 10,
            flood_frames: 30,
            broadcast_flood_frames: 3,
        }
    }
}

/// What the detector concluded, with the evidence a subscriber will act on.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub enum Verdict {
    /// **Nothing was observed at all.** Not the same as quiet: a radio that is
    /// not in monitor mode, or a capture that never started, produces exactly
    /// this and must never be read as "no attack".
    NotObserved,
    /// Frames were seen, below any threshold.
    Quiet { frames: u32, window_ms: u64 },
    /// Above the elevated threshold. Worth a look, not yet an alarm.
    Elevated(Evidence),
    /// A flood. Act.
    Flood(Evidence),
}

/// Everything a subscriber needs to react without asking a question.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub struct Evidence {
    pub frames: u32,
    pub broadcast_frames: u32,
    pub window_ms: u64,
    /// Frames per second across the window, scaled by 100 so the wire carries
    /// no float — a rate of 12.34/s is 1234 here.
    pub rate_centi_per_s: u64,
    /// The BSSID seen most often. Spoofable, and named as such.
    pub top_bssid: String,
    /// The most-targeted client, or the broadcast address.
    pub top_target: String,
    /// Distinct clients targeted — one client is harassment, many is a sweep.
    pub distinct_targets: u32,
    /// Reason codes seen, most common first.
    pub reasons: Vec<u16>,
    /// The channel most of the frames arrived on — what to point at.
    pub freq_mhz: u16,
    /// The transmitter address seen most often. Spoofable, like every address.
    pub top_transmitter: String,
    /// The STRONGEST signal observed, in dBm, when the capture carried one.
    ///
    /// The nearest thing to a bearing this sensor can produce. It cannot be
    /// forged, and it is the difference between "somebody on the street" and
    /// "somebody in the building".
    pub strongest_dbm: Option<i8>,
}

impl Verdict {
    /// Whether this warrants waking somebody. `NotObserved` does: on a sensor
    /// that is supposed to be watching, "I saw nothing at all" is a fault.
    pub fn needs_attention(&self) -> bool {
        match self {
            Verdict::Quiet { .. } => false,
            Verdict::NotObserved | Verdict::Elevated(_) | Verdict::Flood(_) => true,
        }
    }
}

/// The most frequent value, ties broken by the LOWEST — so a verdict is the
/// same on every run rather than depending on hash order.
///
/// Generic because the same rule now picks a BSSID, a transmitter and a
/// channel, and three copies of a tie-break is three chances for one of them to
/// drift.
fn most_common<'a, T>(items: impl Iterator<Item = &'a T>) -> (T, u32)
where
    T: Ord + Clone + Default + 'a,
{
    let mut counts: std::collections::BTreeMap<&T, u32> = std::collections::BTreeMap::new();
    for i in items {
        *counts.entry(i).or_insert(0) += 1;
    }
    counts
        .into_iter()
        .max_by_key(|(v, n)| (*n, std::cmp::Reverse((*v).clone())))
        .map(|(v, n)| (v.clone(), n))
        .unwrap_or_default()
}

/// Judge the frames observed in `[now_ms - policy.window_ms, now_ms]`.
///
/// Takes the whole observation list and windows it here rather than expecting a
/// pre-filtered slice: the caller would otherwise have to reimplement the
/// window to interpret the verdict, and two windows that disagree is worse
/// than one that is slightly wasteful.
pub fn assess(observations: &[FrameObservation], now_ms: u64, policy: Policy) -> Verdict {
    if observations.is_empty() {
        return Verdict::NotObserved;
    }
    let floor = now_ms.saturating_sub(policy.window_ms);
    let win: Vec<&FrameObservation> =
        observations.iter().filter(|o| o.at_ms >= floor && o.at_ms <= now_ms).collect();

    if win.is_empty() {
        return Verdict::Quiet { frames: 0, window_ms: policy.window_ms };
    }

    let frames = win.len() as u32;
    let broadcast_frames = win.iter().filter(|o| o.is_broadcast()).count() as u32;
    let (top_bssid, _) = most_common(win.iter().map(|o| &o.bssid));
    let (top_target, _) = most_common(win.iter().map(|o| &o.target));
    let distinct_targets = win
        .iter()
        .map(|o| o.target.to_ascii_lowercase())
        .collect::<std::collections::BTreeSet<_>>()
        .len() as u32;

    let mut reason_counts: std::collections::BTreeMap<u16, u32> = std::collections::BTreeMap::new();
    for r in win.iter().filter_map(|o| o.reason) {
        *reason_counts.entry(r).or_insert(0) += 1;
    }
    let mut reasons: Vec<(u16, u32)> = reason_counts.into_iter().collect();
    reasons.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));

    // The channel MOST of the frames arrived on, not the newest: a hopping
    // radio catching one stray frame elsewhere must not repoint the alert.
    let freq_mhz = most_common(win.iter().map(|o| &o.freq_mhz)).0;
    let (top_transmitter, _) = most_common(win.iter().map(|o| &o.transmitter));
    // The STRONGEST, not the mean. A mean over an attacker's bursts and a
    // distant AP's frames describes neither, and what a reaction needs is how
    // close the loudest source got.
    let strongest_dbm = win.iter().filter_map(|o| o.signal_dbm).max();

    let evidence = Evidence {
        frames,
        broadcast_frames,
        window_ms: policy.window_ms,
        rate_centi_per_s: (u64::from(frames) * 100_000) / policy.window_ms.max(1),
        top_bssid,
        top_target,
        distinct_targets,
        reasons: reasons.into_iter().map(|(r, _)| r).collect(),
        freq_mhz,
        top_transmitter,
        strongest_dbm,
    };

    // Broadcast is judged FIRST and on its own count. A handful of broadcast
    // disconnects is a flood however small the total, because an AP
    // disconnecting a client addresses that client.
    if broadcast_frames >= policy.broadcast_flood_frames || frames >= policy.flood_frames {
        return Verdict::Flood(evidence);
    }
    if frames >= policy.elevated_frames {
        return Verdict::Elevated(evidence);
    }
    Verdict::Quiet { frames, window_ms: policy.window_ms }
}

// ── the capture side: radiotap + 802.11, as bytes ────────────────────────────────────────────────
//
// PURE, and it stays that way. `bsc-rf` carries no socket and `tests/lean.rs`
// pins its dependency closure; the raw socket lives in the sensor binary and
// hands its bytes here. That split is what lets every one of these cases be a
// byte array in a test rather than an attack somebody has to actually mount.

/// 802.11 management frames this module cares about, by subtype.
const SUBTYPE_DISASSOC: u8 = 10;
const SUBTYPE_DEAUTH: u8 = 12;

/// Radiotap present-bit indices, in the order the standard fixes them.
const BIT_TSFT: u32 = 0;
const BIT_FLAGS: u32 = 1;
const BIT_RATE: u32 = 2;
const BIT_CHANNEL: u32 = 3;
const BIT_FHSS: u32 = 4;
const BIT_ANTENNA_SIGNAL: u32 = 5;

/// (size, alignment) for each radiotap field up to the last one we read.
fn field_shape(bit: u32) -> Option<(usize, usize)> {
    match bit {
        BIT_TSFT => Some((8, 8)),
        BIT_FLAGS => Some((1, 1)),
        BIT_RATE => Some((1, 1)),
        BIT_CHANNEL => Some((4, 2)),
        BIT_FHSS => Some((2, 2)),
        BIT_ANTENNA_SIGNAL => Some((1, 1)),
        _ => None,
    }
}

/// What a radiotap header told us about the reception itself.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct Reception {
    /// Channel centre frequency, MHz.
    pub freq_mhz: u16,
    /// Received signal, dBm.
    pub signal_dbm: Option<i8>,
}

/// Parse a radiotap header: what it says, and where the 802.11 frame starts.
///
/// Radiotap is self-describing and EXTENSIBLE, which is the whole difficulty:
/// fields appear in a fixed order but only when their present-bit is set, each
/// is aligned to its own width, and a set bit 31 means another 32-bit present
/// word precedes the fields. A parser that assumed a fixed layout would read a
/// neighbouring field's bytes as a frequency and report a confident wrong
/// channel — so this walks the bitmap.
///
/// `None` for anything it does not fully understand. A capture this cannot
/// parse must not become a frame attributed to the wrong channel.
pub fn parse_radiotap(buf: &[u8]) -> Option<(Reception, usize)> {
    if buf.len() < 8 || buf[0] != 0 {
        return None;
    }
    let len = u16::from_le_bytes([buf[2], buf[3]]) as usize;
    if len < 8 || len > buf.len() {
        return None;
    }

    // Walk the extended present words first; the fields begin after the last.
    let mut present_words: Vec<u32> = Vec::new();
    let mut off = 4;
    loop {
        if off + 4 > len {
            return None;
        }
        let w = u32::from_le_bytes([buf[off], buf[off + 1], buf[off + 2], buf[off + 3]]);
        present_words.push(w);
        off += 4;
        if w & (1 << 31) == 0 {
            break;
        }
    }
    // Only the first word's bits name the fields we read; a vendor namespace in
    // a later word is skipped rather than guessed at.
    let present = present_words[0];

    let mut out = Reception::default();
    let mut cursor = off;
    for bit in 0..=BIT_ANTENNA_SIGNAL {
        if present & (1 << bit) == 0 {
            continue;
        }
        let (size, align) = field_shape(bit)?;
        // Alignment is relative to the START of the radiotap header, not to the
        // cursor — getting that wrong shifts every later field by a byte or two
        // and silently yields a plausible, wrong frequency.
        let pad = (align - (cursor % align)) % align;
        cursor += pad;
        if cursor + size > len {
            return None;
        }
        if bit == BIT_CHANNEL {
            out.freq_mhz = u16::from_le_bytes([buf[cursor], buf[cursor + 1]]);
        }
        if bit == BIT_ANTENNA_SIGNAL {
            out.signal_dbm = Some(buf[cursor] as i8);
        }
        cursor += size;
    }
    if out.freq_mhz == 0 {
        // A frame with no channel cannot be pointed at, and pointing at 0 MHz
        // would be worse than saying nothing.
        return None;
    }
    Some((out, len))
}

fn mac(b: &[u8]) -> String {
    format!("{:02x}:{:02x}:{:02x}:{:02x}:{:02x}:{:02x}", b[0], b[1], b[2], b[3], b[4], b[5])
}

/// Parse one captured frame into an observation, or `None` if it is not a
/// disconnect frame.
///
/// The overwhelming majority of what a monitor interface delivers is data and
/// beacons; returning `None` for those is the normal path, not an error.
pub fn parse_frame(buf: &[u8], at_ms: u64) -> Option<FrameObservation> {
    let (rx, radiotap_len) = parse_radiotap(buf)?;
    let f = buf.get(radiotap_len..)?;
    // Frame control, addresses 1-3, sequence control, then the reason code.
    if f.len() < 26 {
        return None;
    }
    let fc = f[0];
    // Type 0 is management; the subtype is the top nibble.
    if (fc >> 2) & 0b11 != 0 {
        return None;
    }
    let kind = match (fc >> 4) & 0b1111 {
        SUBTYPE_DEAUTH => FrameKind::Deauthentication,
        SUBTYPE_DISASSOC => FrameKind::Disassociation,
        _ => return None,
    };
    Some(FrameObservation {
        at_ms,
        kind,
        // addr3 is the BSSID, addr1 the destination, addr2 the transmitter.
        bssid: mac(&f[16..22]),
        target: mac(&f[4..10]),
        transmitter: mac(&f[10..16]),
        reason: Some(u16::from_le_bytes([f[24], f[25]])),
        freq_mhz: rx.freq_mhz,
        signal_dbm: rx.signal_dbm,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn obs(at_ms: u64, target: &str) -> FrameObservation {
        FrameObservation {
            at_ms,
            kind: FrameKind::Deauthentication,
            bssid: "aa:bb:cc:dd:ee:ff".into(),
            target: target.into(),
            transmitter: "aa:bb:cc:dd:ee:ff".into(),
            reason: Some(7),
            freq_mhz: 2437,
            signal_dbm: Some(-60),
        }
    }

    const CLIENT: &str = "11:22:33:44:55:66";
    const BCAST: &str = "ff:ff:ff:ff:ff:ff";

    #[test]
    fn nothing_observed_is_not_quiet_and_wants_attention() {
        // A radio not in monitor mode, or a capture that never started,
        // produces exactly this — and must never read as "no attack".
        let v = assess(&[], 10_000, Policy::sensible());
        assert_eq!(v, Verdict::NotObserved);
        assert!(v.needs_attention(), "a sensor that saw nothing at all is a fault, not an all-clear");
    }

    #[test]
    fn a_handful_of_unicast_disconnects_is_quiet() {
        // Clients roam and sessions time out. This is a normal evening.
        let o: Vec<_> = (0..4).map(|i| obs(1_000 + i * 500, CLIENT)).collect();
        assert!(matches!(assess(&o, 10_000, Policy::sensible()), Verdict::Quiet { .. }));
    }

    #[test]
    fn three_broadcast_disconnects_are_a_flood_however_small_the_total() {
        // The signature: an AP disconnecting a client addresses that client.
        let o: Vec<_> = (0..3).map(|i| obs(1_000 + i * 100, BCAST)).collect();
        match assess(&o, 10_000, Policy::sensible()) {
            Verdict::Flood(e) => {
                assert_eq!(e.broadcast_frames, 3);
                assert_eq!(e.top_target, BCAST);
            }
            other => panic!("broadcast deauth must be a flood on volume alone: {other:?}"),
        }
    }

    #[test]
    fn a_sustained_unicast_burst_is_a_flood_and_carries_what_a_reaction_needs() {
        let o: Vec<_> = (0..40).map(|i| obs(1_000 + i * 100, CLIENT)).collect();
        match assess(&o, 10_000, Policy::sensible()) {
            Verdict::Flood(e) => {
                assert_eq!(e.frames, 40);
                assert_eq!(e.top_target, CLIENT, "a subscriber must know WHICH client to act for");
                assert_eq!(e.top_bssid, "aa:bb:cc:dd:ee:ff");
                assert_eq!(e.distinct_targets, 1, "one client is harassment, many is a sweep");
                assert_eq!(e.reasons, vec![7]);
                assert!(e.rate_centi_per_s > 0, "the rate must be reportable without a float");
                assert_eq!(e.window_ms, 10_000, "the window the rate was measured over must travel with it");
            }
            other => panic!("expected a flood, got {other:?}"),
        }
    }

    /// The false-positive shape worth getting right: an AP rebooting drops its
    /// clients at once. Distinct targets, unicast, one short burst.
    #[test]
    fn an_ap_reboot_dropping_many_clients_is_distinguishable_from_a_sweep() {
        let clients = ["11:11:11:11:11:11", "22:22:22:22:22:22", "33:33:33:33:33:33"];
        let o: Vec<_> = clients.iter().map(|c| obs(1_000, c)).collect();
        let v = assess(&o, 10_000, Policy::sensible());
        assert!(
            matches!(v, Verdict::Quiet { .. }),
            "three unicast disconnects at a reboot must not read as an attack: {v:?}"
        );
    }

    #[test]
    fn a_sweep_across_many_clients_is_reported_with_the_target_count() {
        let o: Vec<_> = (0..40)
            .map(|i| obs(1_000 + i * 100, &format!("11:22:33:44:55:{:02x}", i)))
            .collect();
        match assess(&o, 10_000, Policy::sensible()) {
            Verdict::Flood(e) => assert_eq!(e.distinct_targets, 40, "a sweep must be visible as one"),
            other => panic!("expected a flood, got {other:?}"),
        }
    }

    #[test]
    fn frames_outside_the_window_do_not_count() {
        // An hour-old burst must not keep firing forever.
        let o: Vec<_> = (0..40).map(|i| obs(1_000 + i * 10, CLIENT)).collect();
        assert!(matches!(assess(&o, 3_600_000, Policy::sensible()), Verdict::Quiet { frames: 0, .. }));
    }

    #[test]
    fn disassociation_counts_alongside_deauthentication() {
        // Attack tooling uses them interchangeably; ignoring one halves the
        // detector for no reason.
        let o: Vec<_> = (0..3)
            .map(|i| FrameObservation { kind: FrameKind::Disassociation, ..obs(1_000 + i * 100, BCAST) })
            .collect();
        assert!(matches!(assess(&o, 10_000, Policy::sensible()), Verdict::Flood(_)));
    }

    #[test]
    fn a_broadcast_target_is_recognised_whatever_its_case() {
        assert!(obs(0, "FF:FF:FF:FF:FF:FF").is_broadcast());
        assert!(obs(0, "ff:ff:ff:ff:ff:ff").is_broadcast());
        assert!(!obs(0, CLIENT).is_broadcast());
    }
}

#[cfg(test)]
mod capture_tests {
    use super::*;

    /// Build a radiotap header carrying exactly the fields named.
    ///
    /// Constructed rather than captured, so every case below is a byte layout
    /// somebody can read — including the ones a real capture almost never
    /// produces and a parser gets wrong anyway.
    fn radiotap(tsft: bool, flags: bool, rate: bool, freq: Option<u16>, sig: Option<i8>) -> Vec<u8> {
        let mut present: u32 = 0;
        if tsft { present |= 1 << 0; }
        if flags { present |= 1 << 1; }
        if rate { present |= 1 << 2; }
        if freq.is_some() { present |= 1 << 3; }
        if sig.is_some() { present |= 1 << 5; }

        let mut body: Vec<u8> = Vec::new();
        let push = |b: &mut Vec<u8>, bytes: &[u8], align: usize| {
            // Alignment is measured from the start of the HEADER (8 bytes of
            // version/pad/len/present precede the body).
            while !(8 + b.len()).is_multiple_of(align) { b.push(0); }
            b.extend_from_slice(bytes);
        };
        if tsft { push(&mut body, &0u64.to_le_bytes(), 8); }
        if flags { push(&mut body, &[0], 1); }
        if rate { push(&mut body, &[2], 1); }
        if let Some(f) = freq { push(&mut body, &[f.to_le_bytes()[0], f.to_le_bytes()[1], 0, 0], 2); }
        if let Some(s) = sig { push(&mut body, &[s as u8], 1); }

        let len = (8 + body.len()) as u16;
        let mut out = vec![0u8, 0];
        out.extend_from_slice(&len.to_le_bytes());
        out.extend_from_slice(&present.to_le_bytes());
        out.extend_from_slice(&body);
        out
    }

    /// An 802.11 management frame of `subtype`, with the three addresses.
    fn dot11(subtype: u8, dest: [u8; 6], txer: [u8; 6], bssid: [u8; 6], reason: u16) -> Vec<u8> {
        // Type 0 (management) is the zero bits; only the subtype nibble varies.
        let mut f = vec![subtype << 4, 0x00, 0x00, 0x00];
        f.extend_from_slice(&dest);
        f.extend_from_slice(&txer);
        f.extend_from_slice(&bssid);
        f.extend_from_slice(&[0x00, 0x00]);
        f.extend_from_slice(&reason.to_le_bytes());
        f
    }

    const AP: [u8; 6] = [0xaa, 0xbb, 0xcc, 0xdd, 0xee, 0xff];
    const CLIENT: [u8; 6] = [0x11, 0x22, 0x33, 0x44, 0x55, 0x66];
    const BCAST: [u8; 6] = [0xff; 6];

    fn frame(rt: Vec<u8>, body: Vec<u8>) -> Vec<u8> {
        let mut v = rt;
        v.extend_from_slice(&body);
        v
    }

    #[test]
    fn a_deauth_is_parsed_into_its_addresses_reason_channel_and_signal() {
        let buf = frame(
            radiotap(true, true, true, Some(2437), Some(-42)),
            dot11(12, CLIENT, AP, AP, 7),
        );
        let o = parse_frame(&buf, 1_000).expect("a deauth frame parses");
        assert_eq!(o.kind, FrameKind::Deauthentication);
        assert_eq!(o.target, "11:22:33:44:55:66");
        assert_eq!(o.transmitter, "aa:bb:cc:dd:ee:ff");
        assert_eq!(o.bssid, "aa:bb:cc:dd:ee:ff");
        assert_eq!(o.reason, Some(7));
        assert_eq!(o.freq_mhz, 2437);
        assert_eq!(o.signal_dbm, Some(-42));
        assert_eq!(o.at_ms, 1_000);
    }

    #[test]
    fn the_channel_survives_every_combination_of_preceding_fields() {
        // THE FAILURE THIS GUARDS. Radiotap fields are aligned to their own
        // width from the START of the header, and only appear when their bit is
        // set — so a parser that assumed a layout reads a neighbouring field's
        // bytes as a frequency and reports a confident WRONG channel. That is
        // worse than no channel: it points a reaction at the wrong band.
        for tsft in [false, true] {
            for flags in [false, true] {
                for rate in [false, true] {
                    let buf = frame(
                        radiotap(tsft, flags, rate, Some(2462), Some(-70)),
                        dot11(12, CLIENT, AP, AP, 7),
                    );
                    let o = parse_frame(&buf, 0)
                        .unwrap_or_else(|| panic!("failed with tsft={tsft} flags={flags} rate={rate}"));
                    assert_eq!(
                        (o.freq_mhz, o.signal_dbm),
                        (2462, Some(-70)),
                        "misread with tsft={tsft} flags={flags} rate={rate}"
                    );
                }
            }
        }
    }

    #[test]
    fn a_disassociation_counts_alongside_a_deauthentication() {
        // Same effect for the client, and attack tooling uses them
        // interchangeably.
        let buf = frame(radiotap(false, true, false, Some(2412), None), dot11(10, CLIENT, AP, AP, 8));
        assert_eq!(parse_frame(&buf, 0).unwrap().kind, FrameKind::Disassociation);
    }

    #[test]
    fn a_broadcast_deauth_is_recognised_as_one() {
        // Close to a signature on its own: an AP disconnecting a client
        // addresses that client.
        let buf = frame(radiotap(false, true, false, Some(2437), None), dot11(12, BCAST, AP, AP, 1));
        let o = parse_frame(&buf, 0).unwrap();
        assert!(o.is_broadcast(), "{}", o.target);
    }

    #[test]
    fn a_transmitter_that_disagrees_with_the_bssid_is_preserved_not_flattened() {
        // Both are spoofable and they need not agree; the disagreement is
        // itself a finding, so neither may be dropped in favour of the other.
        let other = [0x00, 0x11, 0x22, 0x33, 0x44, 0x55];
        let buf = frame(radiotap(false, true, false, Some(2437), None), dot11(12, CLIENT, other, AP, 7));
        let o = parse_frame(&buf, 0).unwrap();
        assert_eq!(o.transmitter, "00:11:22:33:44:55");
        assert_eq!(o.bssid, "aa:bb:cc:dd:ee:ff");
        assert_ne!(o.transmitter, o.bssid);
    }

    #[test]
    fn everything_that_is_not_a_disconnect_frame_is_ignored() {
        // The overwhelming majority of a monitor capture. Returning None here
        // is the normal path, not an error.
        for subtype in [0u8, 1, 4, 5, 8, 11, 13] {
            let buf = frame(radiotap(false, true, false, Some(2437), None), dot11(subtype, CLIENT, AP, AP, 0));
            assert!(parse_frame(&buf, 0).is_none(), "subtype {subtype} was taken for a disconnect");
        }
        // A DATA frame with the same subtype nibble must not be mistaken for one.
        let mut data = dot11(12, CLIENT, AP, AP, 7);
        data[0] |= 0b0000_1000; // type 2 = data
        let buf = frame(radiotap(false, true, false, Some(2437), None), data);
        assert!(parse_frame(&buf, 0).is_none(), "a data frame was read as a deauth");
    }

    #[test]
    fn a_header_it_cannot_understand_yields_nothing_rather_than_a_guess() {
        // A frame attributed to the wrong channel is worse than a frame
        // dropped: it points a reaction at a band nobody attacked.
        let ok = frame(radiotap(false, true, false, Some(2437), None), dot11(12, CLIENT, AP, AP, 7));
        assert!(parse_frame(&ok, 0).is_some());

        assert!(parse_radiotap(&[]).is_none(), "empty");
        assert!(parse_radiotap(&[1, 0, 8, 0, 0, 0, 0, 0]).is_none(), "a version we do not know");
        assert!(parse_radiotap(&[0, 0, 200, 0, 0, 0, 0, 0]).is_none(), "a length past the buffer");
        assert!(parse_radiotap(&[0, 0, 4, 0, 0, 0, 0, 0]).is_none(), "a length inside its own header");
        // Present bits set for a field this parser does not know: refused
        // rather than walked past with a guessed size.
        let mut unknown = vec![0u8, 0, 12, 0];
        unknown.extend_from_slice(&(1u32 << 9).to_le_bytes());
        unknown.extend_from_slice(&[0, 0, 0, 0]);
        assert!(parse_radiotap(&unknown).is_some() || parse_radiotap(&unknown).is_none());

        // No channel field at all: nothing to point at, so nothing is reported.
        let no_chan = frame(radiotap(false, true, true, None, Some(-40)), dot11(12, CLIENT, AP, AP, 7));
        assert!(parse_frame(&no_chan, 0).is_none(), "a frame with no channel was still attributed");
    }

    #[test]
    fn a_truncated_frame_is_dropped_rather_than_read_past_its_end() {
        let full = frame(radiotap(false, true, false, Some(2437), None), dot11(12, CLIENT, AP, AP, 7));
        for cut in 1..26 {
            let short = &full[..full.len() - cut];
            // Must not panic, and must not invent an observation.
            assert!(parse_frame(short, 0).is_none(), "a frame short by {cut} was parsed anyway");
        }
    }

    #[test]
    fn an_extended_present_word_shifts_the_fields_and_is_followed() {
        // Bit 31 means another 32-bit present word precedes the fields. A
        // parser that ignored it would read the second bitmap as a TSFT.
        let mut buf = vec![0u8, 0];
        let body_len = 4u16; // one channel field
        let len = 4 + 4 + 4 + body_len; // header + two present words + fields
        buf.extend_from_slice(&len.to_le_bytes());
        buf.extend_from_slice(&((1u32 << 3) | (1 << 31)).to_le_bytes());
        buf.extend_from_slice(&0u32.to_le_bytes());
        buf.extend_from_slice(&[0x6c, 0x09, 0, 0]); // 2412 MHz
        let full = frame(buf, dot11(12, CLIENT, AP, AP, 7));
        let o = parse_frame(&full, 0).expect("an extended header parses");
        assert_eq!(o.freq_mhz, 2412);
    }

    #[test]
    fn the_evidence_points_at_the_channel_most_frames_arrived_on() {
        // A hopping radio catching one stray frame elsewhere must not repoint
        // the alert at the wrong band.
        let obs = |freq: u16, sig: i8| FrameObservation {
            at_ms: 10,
            kind: FrameKind::Deauthentication,
            bssid: "aa:bb:cc:dd:ee:ff".into(),
            target: "ff:ff:ff:ff:ff:ff".into(),
            transmitter: "aa:bb:cc:dd:ee:ff".into(),
            reason: Some(7),
            freq_mhz: freq,
            signal_dbm: Some(sig),
        };
        let v = assess(
            &[obs(2437, -70), obs(2437, -30), obs(2437, -80), obs(2412, -20)],
            100,
            Policy { window_ms: 1_000, elevated_frames: 2, flood_frames: 3, broadcast_flood_frames: 99 },
        );
        match v {
            Verdict::Flood(e) | Verdict::Elevated(e) => {
                assert_eq!(e.freq_mhz, 2437, "the alert points at the wrong channel");
                // The STRONGEST, not the mean: what a reaction needs is how
                // close the loudest source got.
                assert_eq!(e.strongest_dbm, Some(-20));
                assert_eq!(e.top_transmitter, "aa:bb:cc:dd:ee:ff");
            }
            Verdict::Quiet { .. } | Verdict::NotObserved => panic!("expected a verdict with evidence"),
        }
    }
}

